import { Component, OnDestroy, ChangeDetectorRef, ChangeDetectionStrategy } from '@angular/core';
import { Package } from '@imunify360-api/license';
import { AuthState } from 'app/services/auth-state';
import { AppState } from 'app/core/app.service';
import { AgentStatus } from '@imunify360-api/misc';
import { combineLatestWith, takeUntil, Subject } from 'rxjs';
import { InstallationBackendService } from '../installation-backend.service';

@Component({
    selector: 'installation-tabs',
    templateUrl: './installation-tabs.component.html',
    styleUrls: ['./installation-tabs.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class InstallationTabsComponent implements OnDestroy {
    isAdmin: boolean = false;
    isUpgrading: boolean = false;
    showLog: boolean = false;
    is360 = IMUNIFY_PACKAGE === Package.imunify360;

    private destroy$ = new Subject<void>();

    constructor(
        private cdr: ChangeDetectorRef,
        private authState: AuthState,
        private appState: AppState,
        private installationBackendService: InstallationBackendService,
    ) {
        this.checkShowTabs();
    }

    ngOnDestroy(): void {
        this.destroy$.next();
    }

    private checkShowTabs(): void {
        this.authState.isAdmin.pipe(
            combineLatestWith(this.appState.imunifyStatus),
            takeUntil(this.destroy$),
        ).subscribe(([isAdmin, imunifyStatus]) => {
            this.isUpgrading = imunifyStatus === AgentStatus.UPGRADING;
            this.isAdmin = isAdmin;

            if (this.isUpgrading) {
                this.checkUpgradeLogIsAvailable();
            }

            this.cdr.markForCheck();
        });
    }

    private checkUpgradeLogIsAvailable(): void {
        this.installationBackendService.upgradeStatus({ offset: 0, limit: 1 })
            .pipe(takeUntil(this.destroy$))
            .subscribe({
                next: res => {
                    this.showLog = !res.data.items?.log?.includes('Error reading file i360deploy.log');
                    this.cdr.markForCheck();
                },
                error: () => {
                    this.showLog = false;
                    this.cdr.markForCheck();
                }
            });
    }
}
