import { Component, Input, OnChanges, SimpleChanges } from '@angular/core';
import { getImagePath } from 'app/core/misc';
import { APP_NAMES } from 'app/core/app-names.enum';

@Component({
    selector: 'preview-screenshot',
    template: `
        <div class="buy_license_screenshot">
            <div class="screenshot_toolbar">
                <span class="screenshot_button"></span>
                <span class="screenshot_button"></span>
                <span class="screenshot_button"></span>
            </div>
            <img [src]="imagePath">
        </div>
    `,
    styleUrls: ['./preview-screenshot.component.scss'],
})
export class PreviewScreenshotComponent implements OnChanges {
    @Input() screenshotName: string = '';
    imagePath: string;

    ngOnChanges(changes: SimpleChanges) {
        if ('screenshotName' in changes) {
            this.imagePath = `${getImagePath()}/${APP_NAMES.OTHER_ROOT}/${this.screenshotName}.png`;
        }
    }
}

