import { ChangeDetectionStrategy, Component, OnDestroy } from '@angular/core';
import { InstallationBackendService } from 'app/components/installation/installation-backend.service';
import { STATUS_REFRESH_INTERVAL, LOG_CHUNK_SIZE } from 'app/components/installation/installation.service';
import { Router } from '@angular/router';
import { Subject, timer, switchMap, catchError, repeat, takeUntil } from 'rxjs';

@Component({
    selector: 'installation-downgrading',
    template: `
        <div class="installation-downgrading__container">
            <spinner [show]="true" color="green"></spinner>
        </div>
    `,
    styles: [`
        .installation-downgrading__container {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 100%;
            min-height: 320px;
        }
    `],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DowngradingComponent implements OnDestroy {
    private destroy$ = new Subject<void>();
    private offset = 0;

    constructor(
        private router: Router,
        private installationBackendService: InstallationBackendService,
    ) {
        this.startPollingStatus();
    }

    ngOnDestroy() {
        this.destroy$.next();
    }

    private startPollingStatus(): void {
        timer(0).pipe(
            switchMap(() => this.installationBackendService.status({ offset: 0, limit: 1 })),
            catchError(() => timer(STATUS_REFRESH_INTERVAL)),
            repeat({ delay: STATUS_REFRESH_INTERVAL }),
            takeUntil(this.destroy$),
        ).subscribe();
    }
}
